// ---------------------------------------------------------------- collision groups
const GRP = { ENV: 1, CAR: 2, DEBRIS: 4, BRICK: 8 };
const ALL = GRP.ENV | GRP.CAR | GRP.DEBRIS | GRP.BRICK;
const groups = (member, filter) => ((member & 0xffff) << 16) | (filter & 0xffff);
const GROUP_ENV = groups(GRP.ENV, ALL);
const GROUP_CAR = groups(GRP.CAR, GRP.ENV | GRP.DEBRIS | GRP.BRICK); // attached parts ignore each other
const GROUP_DEBRIS = groups(GRP.DEBRIS, ALL);
const GROUP_BRICK = groups(GRP.BRICK, ALL);

// ---------------------------------------------------------------- environment (track, curbs, barriers, lights)
let envGroup = null;
function staticBox(world, cx, cy, cz, hx, hy, hz, friction, restitution = 0.1) {
  const body = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(cx, cy, cz));
  const col = world.createCollider(RAPIER.ColliderDesc.cuboid(hx, hy, hz).setFriction(friction).setRestitution(restitution).setCollisionGroups(GROUP_ENV), body);
  return col;
}
function buildEnvironment(world, s, carX0, wallX) {
  const g = new THREE.Group(); envGroup = g; scene.add(g);
  const L = s.trackLength, x0 = -L / 2 - 4, x1 = L / 2 + 6, len = x1 - x0, cx = (x0 + x1) / 2;
  const mesh = (geo, mat, x, y, z, cast = false, recv = true) => { const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.castShadow = cast; m.receiveShadow = recv; g.add(m); return m; };
  const grass = mesh(new THREE.PlaneGeometry(700, 700), MAT.grass, 0, -0.012, 0); grass.rotation.x = -Math.PI / 2;
  for (const side of [-1, 1]) { const gr = mesh(new THREE.PlaneGeometry(len + 6, 1.9), MAT.gravel, cx, -0.004, side * 5.4); gr.rotation.x = -Math.PI / 2; }
  const asphalt = mesh(new THREE.PlaneGeometry(len, 8), new THREE.MeshStandardMaterial({ map: asphaltTexture(x0, x1, carX0, wallX), bumpMap: asphaltTexture(x0, x1, carX0, wallX), bumpScale: 0.004, roughness: 0.93, metalness: 0.0 }), cx, 0.0, 0);
  asphalt.rotation.x = -Math.PI / 2;
  for (const side of [-1, 1]) {
    mesh(new THREE.BoxGeometry(len, 0.07, 0.45), MAT.curb, cx, 0.035, side * 4.225, true);
    staticBox(world, cx, 0.035, side * 4.225, len / 2, 0.035, 0.225, 0.8);
    mesh(new THREE.BoxGeometry(len + 4, 0.32, 0.06), MAT.armco, cx, 0.62, side * 6.6, true);
    mesh(new THREE.BoxGeometry(len + 4, 0.06, 0.06), MAT.armco, cx, 0.28, side * 6.6, true);
    staticBox(world, cx, 0.45, side * 6.6, len / 2 + 2, 0.4, 0.04, 0.6);
    const n = Math.floor((len + 4) / 2), posts = new THREE.InstancedMesh(new THREE.BoxGeometry(0.1, 0.78, 0.1), MAT.pole, n);
    posts.castShadow = true; const M = new THREE.Matrix4();
    for (let i = 0; i < n; i++) { M.makeTranslation(x0 - 2 + 1 + i * 2, 0.39, side * 6.66); posts.setMatrixAt(i, M); }
    g.add(posts);
  }
  for (let i = 0; i < 6; i++) {
    const px = x0 + 2 + i * (len - 4) / 5, side = i % 2 ? 1 : -1;
    const pole = mesh(new THREE.CylinderGeometry(0.07, 0.11, 9.5, 12), MAT.pole, px, 4.75, side * 8.4, true, false);
    const arm = mesh(new THREE.BoxGeometry(0.16, 0.16, 2.4), MAT.pole, px, 9.35, side * 7.3, true, false);
    mesh(new THREE.BoxGeometry(0.9, 0.18, 0.5), MAT.lamp, px, 9.3, side * 6.2, true, false);
    void pole; void arm;
  }
  // distant treeline for horizon depth (no shadows)
  const trees = new THREE.InstancedMesh(new THREE.ConeGeometry(2.6, 8, 6), MAT.tree, 140), rng = mulberry32(99), M = new THREE.Matrix4(), col = new THREE.Color();
  for (let i = 0; i < 140; i++) {
    const a = (i / 140) * Math.PI * 2, r = 120 + rng() * 60, sc = 0.8 + rng() * 0.9;
    M.compose(V3(Math.cos(a) * r, 4 * sc, Math.sin(a) * r), new THREE.Quaternion(), V3(sc, sc, sc)); trees.setMatrixAt(i, M);
    col.setHSL(0.28 + rng() * 0.06, 0.35, 0.16 + rng() * 0.12); trees.setColorAt(i, col);
  }
  g.add(trees);
  // physics ground
  const ground = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(0, -1, 0));
  const gcol = world.createCollider(RAPIER.ColliderDesc.cuboid(400, 1, 400).setFriction(s.groundFriction).setRestitution(0.05).setCollisionGroups(GROUP_ENV), ground);
  fitShadowToBox(x0 - 1, x1 + 2, -8.5, 8.5, 4.5);
