    gF.colliders.push({ type: 'hull', poly: [[-0.18, 0.94], [0.86, 0.94], [0.36, 1.38], [-0.18, 1.38]].map(([x, y]) => [x * sx, y * sy]), z: zs * 0.86 * sz, t: 0.008, mass: 4 * mScale, mat: 'glass' });
    const gR = part('glassR' + side, [-0.78, 1.16, zs * 0.86], { mat: 'glass', glass: true, fBreak: 1200 });
    gR.colliders.push({ type: 'hull', poly: [[-1.26, 0.94], [-0.34, 0.94], [-0.34, 1.38], [-1.02, 1.38]].map(([x, y]) => [x * sx, y * sy]), z: zs * 0.86 * sz, t: 0.008, mass: 4 * mScale, mat: 'glass' });
    // thresholds: inertial load in g on the lighter body, or direct contact force in N
    joint('fender' + side, 'engineBay', [1.3, 0.7, zs * 0.84], 8, 5000);
    joint('doorF' + side, 'cabin', [0.85, 0.62, zs * 0.875], 16, 30000, 'revolute', [0, 1, 0]);
    joint('doorF' + side, 'cabin', [-0.2, 0.62, zs * 0.875], 3.2, 6000);
    joint('doorR' + side, 'cabin', [-0.31, 0.62, zs * 0.875], 18, 30000, 'revolute', [0, 1, 0]);
    joint('doorR' + side, 'cabin', [-1.28, 0.62, zs * 0.875], 3.6, 6000);
