  raked(ws, [0.9, 0.93], [0.3, 1.40], 0, 1.36, 0.012, 14);
  const rg = part('rearGlass', [-1.25, 1.195, 0], { mat: 'glass', glass: true, fBreak: 1500 });
  raked(rg, [-1.5, 0.99], [-1.0, 1.40], 0, 1.36, 0.012, 10);
  const wheelDefs = [['wheelFL', 1.3, 0.70, 'engineBay', 14, 25000], ['wheelFR', 1.3, -0.70, 'engineBay', 14, 25000], ['wheelRL', -1.4, 0.70, 'cabin', 22, 50000], ['wheelRR', -1.4, -0.70, 'cabin', 22, 50000]];
  for (const [name, x, z, parent, gB, fB] of wheelDefs) {
