  joint('nose', 'engineBay', [1.5, 0.55, 0], 16, 80000);
  joint('engine', 'engineBay', [1.12, 0.4, 0], 14, 60000);
  joint('frontBumper', 'nose', [2.0, 0.48, 0], 8, 3000);
  joint('rearBumper', 'cabin', [-2.01, 0.5, 0], 18, 30000);
  joint('hood', 'engineBay', [0.96, 0.905, 0], 14, 20000, 'revolute', [0, 0, 1]);
  joint('hood', 'engineBay', [1.96, 0.925, 0], 4, 5000);
  joint('trunk', 'cabin', [-1.51, 0.95, 0], 22, 30000, 'revolute', [0, 0, 1]);
  joint('trunk', 'cabin', [-1.98, 0.95, 0], 5, 15000);
  joint('windshield', 'cabin', [0.6, 1.165, 0], 4, 1200);
  joint('rearGlass', 'cabin', [-1.25, 1.195, 0], 5, 1200);
  return { parts, joints, R, HW, sx, sy, sz };
}

// ---------------------------------------------------------------- simulation state
const sim = {
  world: null, events: null, dt: 1 / 120, t: 0, settling: true,
  parts: [], partByName: new Map(), joints: [], bricks: [], shards: [], colInfo: new Map(),
  carGroup: null, brickMesh: null, shardMesh: null, fx: [],
  impactT: -1, driving: false, settledT: -1, phase: 'approach', wallX: 0, carX0: 0, wallW: 6, wallH: 2,
  vTarget: 22, aMax: 10, carMassTotal: 1250, prng: null, def: null, aliveJoints: 0,
};
const SHARD_CAP = 110;
const tmpM = new THREE.Matrix4(), tmpQ = new THREE.Quaternion(), tmpV = new THREE.Vector3(), tmpS = new THREE.Vector3();
function disposeGroup(g) { g.traverse((o) => { if (o.geometry) o.geometry.dispose(); }); if (g.parent) g.parent.remove(g); }

function boxGeo(s, round) {
  const r = round ? Math.min(round, Math.min(s[0], s[1], s[2]) * 0.49) : 0;
  return r > 0 ? new RoundedBoxGeometry(s[0], s[1], s[2], 2, r) : new THREE.BoxGeometry(s[0], s[1], s[2]);
}
function addMesh(group, geo, mat, local, q = null) {
  const m = new THREE.Mesh(geo, mat); m.position.set(local[0], local[1], local[2]); if (q) m.quaternion.copy(q);
  m.castShadow = true; m.receiveShadow = true; group.add(m); return m;
}
function wheelMesh(R, HW) {
  const g = new THREE.Group();
  const cyl = (r, h, seg) => { const geo = new THREE.CylinderGeometry(r, r, h, seg); geo.rotateX(Math.PI / 2); return geo; };
  addMesh(g, cyl(R, HW * 2, 32), MAT.rubber, [0, 0, 0]);
  addMesh(g, cyl(R * 0.62, HW * 2 + 0.012, 24), MAT.rim, [0, 0, 0]);
  addMesh(g, cyl(R * 0.5, HW * 2 - 0.03, 24), MAT.trim, [0, 0, 0]);
  addMesh(g, cyl(R * 0.13, HW * 2 + 0.04, 12), MAT.chrome, [0, 0, 0]);
  for (let i = 0; i < 5; i++) { const q = new THREE.Quaternion().setFromAxisAngle(V3(0, 0, 1), i * Math.PI * 2 / 5); const sp = addMesh(g, new THREE.BoxGeometry(R * 0.5, 0.05, HW * 2 + 0.02), MAT.rim, [0, 0, 0], q); sp.position.set(Math.cos(i * Math.PI * 2 / 5) * R * 0.28, Math.sin(i * Math.PI * 2 / 5) * R * 0.28, 0); }
  return g;
}
function buildExtras(part, group, def) {
  const { sx, sy, sz } = def, pos = part.pos;
  const L = (x, y, z) => [x * sx - pos[0], y * sy - pos[1], z * sz - pos[2]];
  const S = (w, h, d) => [w * sx, h * sy, d * sz];
  const B = (c, s, mat, round = 0, q = null) => addMesh(group, boxGeo(S(...s), round), mat, L(...c), q);
  switch (part.extras) {
    case 'cabin':
      for (const zs of [-1, 1]) {
        B([-2.0, 0.78, zs * 0.55], [0.03, 0.12, 0.42], MAT.taillight);
        B([0.0, 0.70, zs * 0.42], [0.55, 0.16, 0.5], MAT.interior, 0.04); B([-0.25, 1.0, zs * 0.42], [0.12, 0.55, 0.5], MAT.interior, 0.04);
        B([0.72, 1.02, zs * 0.96], [0.14, 0.09, 0.2], MAT.trim, 0.02);
      }
      B([-1.05, 0.70, 0], [0.5, 0.16, 1.3], MAT.interior, 0.04); B([-1.22, 0.95, 0], [0.1, 0.42, 1.3], MAT.interior, 0.04);
      B([0.55, 0.97, 0], [0.3, 0.1, 1.5], MAT.interior, 0.03);
      B([-2.0, 0.55, 0], [0.02, 0.14, 0.5], MAT.chrome);
      B([-0.55, 0.29, 0], [2.6, 0.03, 1.5], MAT.under);
      addMesh(group, new THREE.TorusGeometry(0.17, 0.02, 10, 24), MAT.trim, L(0.38, 1.02, 0.42), qZ(-20).multiply(qY(90)));
      break;
    case 'nose':
      for (const zs of [-1, 1]) { B([1.995, 0.79, zs * 0.5], [0.03, 0.12, 0.36], MAT.headlight); B([1.985, 0.79, zs * 0.5], [0.04, 0.17, 0.42], MAT.trim); }
      B([1.995, 0.79, 0], [0.03, 0.12, 0.56], MAT.trim); B([2.0, 0.77, 0], [0.02, 0.02, 0.56], MAT.chrome); B([2.0, 0.81, 0], [0.02, 0.02, 0.56], MAT.chrome);
      break;
    case 'frontBumper': B([2.07, 0.33, 0], [0.13, 0.07, 1.72], MAT.trim, 0.02); break;
    case 'engine': B([1.12, 0.86, 0], [0.26, 0.06, 0.34], MAT.trim, 0.02); addMesh(group, new THREE.CylinderGeometry(0.05, 0.05, 0.5, 12), MAT.chrome, L(1.29, 0.78, 0), qX(90)); break;
    case 'door': { const zs = Math.sign(pos[2]); const x = pos[0] / sx + 0.32; B([x, 0.82, zs * 0.905], [0.16, 0.03, 0.03], MAT.chrome, 0.01); B([pos[0] / sx, 0.36, zs * 0.905], [0.9, 0.05, 0.02], MAT.trim); break; }
    case 'wheel': { const w = wheelMesh(def.R, def.HW); group.add(w); part.spin = w; break; }
  }
}

// ---------------------------------------------------------------- reset / build
function reset(s) {
  if (sim.world) { sim.world.free(); sim.events.free(); }
  for (const g of [sim.carGroup, sim.brickMesh, sim.shardMesh, envGroup]) if (g) disposeGroup(g);
  Object.assign(sim, { t: 0, settling: true, parts: [], partByName: new Map(), joints: [], bricks: [], shards: [], colInfo: new Map(), fx: [], impactT: -1, driving: false, settledT: -1, phase: 'approach', aliveJoints: 0 });
  sim.prng = mulberry32(4242);
  sim.g = s.gravity;
  fxReset();
  const world = new RAPIER.World({ x: 0, y: -s.gravity, z: 0 });
  world.timestep = sim.dt;
  try { world.integrationParameters.numSolverIterations = 8; } catch (e) { /* older API */ }
  const events = new RAPIER.EventQueue(true);
  sim.world = world; sim.events = events;

  const L = s.trackLength;
  const carX0 = -L / 2 + 1 + s.carLength / 2, wallX = L / 2 - 8;
  sim.carX0 = carX0; sim.wallX = wallX;
  const env = buildEnvironment(world, s, carX0, wallX);
  sim.colInfo.set(env.groundHandle, { kind: 'ground' });

  // --- brick wall: running bond, individual rigid bodies, both wythes real
  const bw = s.brickW, bh = s.brickH, bd = s.brickD, cols = s.wallCols, rows = s.wallRows, depth = s.wallDepth;
  const W = cols * bw; sim.wallW = W; sim.wallH = rows * bh;
  const brickList = [];
  const brick = (x, y, z, w) => brickList.push({ x, y, z, w });
  for (let layer = 0; layer < depth; layer++) {
    const x = wallX - depth * bd / 2 + bd / 2 + layer * bd;
    for (let row = 0; row < rows; row++) {
      const y = row * bh + bh / 2, stagger = ((row + layer) % 2) === 1;
      if (!stagger) { for (let c = 0; c < cols; c++) brick(x, y, -W / 2 + bw / 2 + c * bw, bw); }
      else {
        brick(x, y, -W / 2 + bw / 4, bw / 2);
        for (let c = 0; c < cols - 1; c++) brick(x, y, -W / 2 + bw + c * bw, bw);
        brick(x, y, W / 2 - bw / 4, bw / 2);
      }
    }
  }
  const brickMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), MAT.brick, brickList.length);
  brickMesh.castShadow = true; brickMesh.receiveShadow = true; brickMesh.frustumCulled = false;
  const brng = mulberry32(31), col = new THREE.Color();
  brickList.forEach((b, i) => {
    const body = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(b.x, b.y, b.z).setCanSleep(true).setCcdEnabled(true).setLinearDamping(0.02).setAngularDamping(0.08));
    const c = world.createCollider(RAPIER.ColliderDesc.cuboid(bd / 2, bh / 2, b.w / 2).setMass(s.brickMass * (b.w / bw)).setFriction(s.brickFriction).setRestitution(s.brickRestitution)
      .setCollisionGroups(GROUP_BRICK).setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS).setContactForceEventThreshold(450), body);
    sim.colInfo.set(c.handle, { kind: 'brick', ref: body });
    sim.bricks.push({ body, size: [bd, bh, b.w], i });
    col.setHSL(0.03 + brng() * 0.04, 0.42 + brng() * 0.2, 0.36 + brng() * 0.16); brickMesh.setColorAt(i, col);
    tmpM.compose(V3(b.x, b.y, b.z), tmpQ.identity(), V3(bd, bh, b.w)); brickMesh.setMatrixAt(i, tmpM);
  });
  brickMesh.instanceColor.needsUpdate = true; brickMesh.instanceMatrix.needsUpdate = true;
  scene.add(brickMesh); sim.brickMesh = brickMesh;

  // --- car: separate rigid bodies + breakable joints
  const def = buildCarDef(s); sim.def = def;
  const carGroup = new THREE.Group(); scene.add(carGroup); sim.carGroup = carGroup;
  let massTotal = 0;
  for (const p of def.parts) {
    const body = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(carX0 + p.pos[0], p.pos[1], p.pos[2]).setCanSleep(true).setCcdEnabled(true).setLinearDamping(0.01).setAngularDamping(0.05));
    const group = new THREE.Group(); carGroup.add(group);
    p.body = body; p.mesh = group; p.mass = 0; p.cols = []; p.joints = []; p.contactF = 0; p.aEst = 0; p.pv = { x: 0, y: 0, z: 0 }; p.loosened = false; p.detached = false; p.pendingShatter = false;
    for (const c of p.colliders) {
      let desc;
      const mat = MAT[c.mat || p.mat];
      if (c.type === 'box') {
        const lc = [c.c[0] - p.pos[0], c.c[1] - p.pos[1], c.c[2] - p.pos[2]];
        desc = RAPIER.ColliderDesc.cuboid(c.s[0] / 2, c.s[1] / 2, c.s[2] / 2).setTranslation(...lc);
        if (c.q) desc.setRotation({ x: c.q.x, y: c.q.y, z: c.q.z, w: c.q.w });
        addMesh(group, boxGeo(c.s, c.round), mat, lc, c.q);
      } else if (c.type === 'cyl') {
        desc = RAPIER.ColliderDesc.cylinder(c.hw, c.r).setRotation({ x: c.q.x, y: c.q.y, z: c.q.z, w: c.q.w });
      } else { // convex hull glass pane
        const pts = [];
        for (const dz of [-c.t / 2, c.t / 2]) for (const [x, y] of c.poly) pts.push(x - p.pos[0], y - p.pos[1], dz);
        desc = RAPIER.ColliderDesc.convexHull(new Float32Array(pts));
        const shape = new THREE.Shape(c.poly.map(([x, y]) => new THREE.Vector2(x - p.pos[0], y - p.pos[1])));
        const geo = new THREE.ExtrudeGeometry(shape, { depth: c.t, bevelEnabled: false }); geo.translate(0, 0, -c.t / 2);
        addMesh(group, geo, mat, [0, 0, 0]);
      }
      desc.setMass(c.mass).setRestitution(0.05).setCollisionGroups(GROUP_CAR).setActiveEvents(RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS).setContactForceEventThreshold(400);
      if (p.wheel) desc.setFriction(0.0).setFrictionCombineRule(RAPIER.CoefficientCombineRule.Min); else desc.setFriction(p.glass ? 0.3 : 0.5);
      const collider = world.createCollider(desc, body);
      p.cols.push(collider); p.mass += c.mass;
      sim.colInfo.set(collider.handle, { kind: 'part', ref: p });
    }
    if (p.extras) buildExtras(p, group, def);
    massTotal += p.mass;
    sim.parts.push(p); sim.partByName.set(p.name, p);
  }
  sim.carMassTotal = massTotal;
  for (const jd of def.joints) {
    const a = sim.partByName.get(jd.a), b = sim.partByName.get(jd.b);
    const a1 = { x: jd.pt[0] - a.pos[0], y: jd.pt[1] - a.pos[1], z: jd.pt[2] - a.pos[2] };
    const a2 = { x: jd.pt[0] - b.pos[0], y: jd.pt[1] - b.pos[1], z: jd.pt[2] - b.pos[2] };
    const data = jd.type === 'revolute' ? RAPIER.JointData.revolute(a1, a2, { x: jd.axis[0], y: jd.axis[1], z: jd.axis[2] }) : RAPIER.JointData.fixed(a1, Q_ID, a2, Q_ID);
    const joint = world.createImpulseJoint(data, a.body, b.body, true);
    const rec = { joint, a, b, gBreak: jd.gBreak, fBreak: jd.fBreak, alive: true };
    sim.joints.push(rec); a.joints.push(rec); b.joints.push(rec); sim.aliveJoints++;
  }
  const shardMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), MAT.shard, SHARD_CAP);
  shardMesh.castShadow = true; shardMesh.receiveShadow = true; shardMesh.frustumCulled = false;
  tmpM.makeScale(0, 0, 0); for (let i = 0; i < SHARD_CAP; i++) shardMesh.setMatrixAt(i, tmpM);
  shardMesh.instanceMatrix.needsUpdate = true; scene.add(shardMesh); sim.shardMesh = shardMesh;

  // speed plan: accelerate, then hold the target speed until the wall
  sim.vTarget = s.speed;
  const dist = (wallX - depth * bd / 2) - (carX0 + s.carLength / 2);
  sim.aMax = Math.max(9, s.speed * s.speed / (2 * Math.max(dist - 4, 3)));

  // deterministic pre-roll so joints and contacts settle before the run
  for (let i = 0; i < 24; i++) world.step(events);
  events.drainContactForceEvents(() => {});
  for (const p of sim.parts) { const v = p.body.linvel(); p.pv = { x: v.x, y: v.y, z: v.z }; }
  sim.settling = false; sim.driving = true;
  syncMeshes(0);
  cameraReset();
}

// ---------------------------------------------------------------- breakage
function setGroup(p, grp) { for (const c of p.cols) c.setCollisionGroups(grp); }
function loosen(p) {
  if (p.loosened) return;
