    addMesh(group, boxGeo(c.s, c.round), mat, lc, c.q);
    fpX = Math.max(fpX, Math.abs(lc[0]) + c.s[0] / 2); fpZ = Math.max(fpZ, Math.abs(lc[2]) + c.s[2] / 2); fpBottom = Math.min(fpBottom, lc[1] - c.s[1] / 2);
  } else if (c.type === 'cyl') {
    desc = RAPIER.ColliderDesc.cylinder(c.hw, c.r).setRotation({ x: c.q.x, y: c.q.y, z: c.q.z, w: c.q.w });
