const panel = document.getElementById('panel');
function buildPanel() {
  let html = '';
  for (const grp of SCHEMA) {
    html += `<h2>${grp.group}</h2>`;
    for (const [key, label, unit, min, max, step] of grp.items) html += `<label><span>${label}</span><input type="number" data-key="${key}" min="${min}" max="${max}" step="${step}" value="${settings[key]}"><span class="unit">${unit}</span></label>`;
  }
  html += `<div class="actions"><button id="btnApply" class="primary">Replay with values</button><button id="btnDefaults">Defaults</button></div>
    <div class="note">Replay reruns the rigid-body simulation with these values (fixed 120 Hz step, seeded). The defaults reproduce the baseline crash on every load.</div>`;
  panel.innerHTML = html;
  document.getElementById('btnApply').addEventListener('click', replay);
  document.getElementById('btnDefaults').addEventListener('click', () => { settings = { ...DEFAULTS }; fillPanel(); reset(settings); });
}
function fillPanel() { panel.querySelectorAll('input').forEach((inp) => { inp.value = settings[inp.dataset.key]; }); }
function readPanel() {
  const s = { ...settings };
  panel.querySelectorAll('input').forEach((inp) => {
    const key = inp.dataset.key, v = parseFloat(inp.value);
    if (Number.isFinite(v)) { let c = clamp(v, parseFloat(inp.min), parseFloat(inp.max)); if (parseFloat(inp.step) === 1) c = Math.round(c); s[key] = c; }
    inp.value = s[key];
  });
  return s;
}
function replay() { settings = readPanel(); reset(settings); }
document.getElementById('btnReplay').addEventListener('click', replay);
document.getElementById('btnSettings').addEventListener('click', () => panel.classList.toggle('open'));
window.addEventListener('keydown', (e) => { if ((e.key === 'r' || e.key === 'R') && !(e.target instanceof HTMLInputElement)) replay(); });

// ---------------------------------------------------------------- main loop: fixed 120 Hz physics, interpolation-free render sync
let last = performance.now(), acc = 0;
const dbSize = new THREE.Vector2();
function frame(now) {
  requestAnimationFrame(frame);
  const dtF = Math.min((now - last) / 1000, 0.1); last = now;
  acc += dtF; let n = 0;
  while (acc >= sim.dt && n < 6) { physicsStep(); acc -= sim.dt; n++; }
  if (n === 6) acc = 0;
  syncMeshes(dtF);
  renderer.getDrawingBufferSize(dbSize);
  const pScale = dbSize.y / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
  dust.update(dtF, pScale); sparks.update(dtF, pScale);
  updatePhase(); updateCamera(dtF, now); updateHUD();
  composer.render();
}
buildPanel();
reset(settings);
document.getElementById('loading').classList.add('hide');
requestAnimationFrame(frame);
</script>
