const cabin = sim.partByName.get('cabin');
// Drive: the same acceleration is applied to every part in proportion to its mass, so the car
// accelerates as one rigid body and the breakable joints carry no drivetrain load before impact.
const aCmd = sim.driving ? clamp((sim.vTarget - cabin.body.linvel().x) * 20, -sim.aMax, sim.aMax) : 0;
for (const p of sim.parts) {
  p.contactF = 0;
  if (!p.body) continue;
  p.body.resetForces(false);
  if (aCmd !== 0) p.body.addForce({ x: aCmd * p.mass, y: 0, z: 0 }, true);
}

