function updatePhase() {
  if (sim.phase !== 'impact') return;
  const since = sim.t - sim.impactT;
  if (since > 2.5) {
    let vmax = 0;
    for (const p of sim.parts) { if (!p.body) continue; const v = p.body.linvel(); vmax = Math.max(vmax, Math.hypot(v.x, v.y, v.z)); }
    for (const b of sim.bricks) { if (b.body.isSleeping()) continue; const v = b.body.linvel(); vmax = Math.max(vmax, Math.hypot(v.x, v.y, v.z)); }
    if (vmax < 0.3) { if (sim.settledT < 0) sim.settledT = sim.t; } else sim.settledT = -1;
    if ((sim.settledT >= 0 && sim.t - sim.settledT > 1.5) || since > 14) enterOrbit();
  }
}
function enterOrbit() {
  sim.phase = 'settled'; const c = wreckCenter(tmpV);
  cam.orbitStart = sim.t; cam.orbitBase = Math.atan2(cam.pos.z - c.z, cam.pos.x - c.x); cam.orbitR = Math.hypot(cam.pos.x - c.x, cam.pos.z - c.z); cam.orbitH = cam.pos.y;
}

