controls.enabled = false; controls.enableDamping = true; controls.maxPolarAngle = Math.PI / 2 - 0.03; controls.minDistance = 3; controls.maxDistance = 90;
const takeManual = () => { if (cam.manual) return; cam.manual = true; controls.target.copy(cam.tgt); controls.enabled = true; };
