function wreckCenter(out) {
  // mass-weighted centre of the parts still near the cabin (a tyre rolling off down the track must not drag the framing)
  const cab = sim.partByName.get('cabin').body.translation();
  out.set(0, 0, 0); let m = 0;
  for (const p of sim.parts) {
    if (!p.body) continue; const t = p.body.translation();
    if (Math.hypot(t.x - cab.x, t.z - cab.z) > 9) continue;
    out.x += t.x * p.mass; out.y += t.y * p.mass; out.z += t.z * p.mass; m += p.mass;
  }
  if (m > 0) out.multiplyScalar(1 / m); out.y = Math.max(out.y, 0.7); return out;
}

