// Shadow frustum hugs the action: the wall plus every car part wherever it ended up, nothing else.
function updateShadowFrustum() {
  const wallX = sim.wallX;
  let minX = wallX - 6, maxX = wallX + 8, minZ = -6, maxZ = 6;
  for (const p of sim.parts) {
    if (!p.body) continue; const t = p.body.translation();
    minX = Math.min(minX, t.x - 3); maxX = Math.max(maxX, t.x + 3); minZ = Math.min(minZ, t.z - 2.5); maxZ = Math.max(maxZ, t.z + 2.5);
  }
  fitShadowToBox(minX, Math.min(maxX, minX + 70), Math.max(minZ, -12), Math.min(maxZ, 12), 3.6);
}

